    28	@Component
    29	public class CalculadoraCheckout {
    31	    private static final Pattern CEP = Pattern.compile("\\d{8}");
    33	    private final ProdutoRepositorio produtos;
    34	    private final NiveisClube niveis;
    35	    private final ModalidadesEntrega modalidades;
    36	    private final Cupons cupons;
    37	    private final FormasPagamento formasPagamento;
    39	    public CalculadoraCheckout(ProdutoRepositorio produtos, NiveisClube niveis, ModalidadesEntrega modalidades,
    40	                               Cupons cupons, FormasPagamento formasPagamento) {
    41	        this.produtos = produtos;
    42	        this.niveis = niveis;
    43	        this.modalidades = modalidades;
    44	        this.cupons = cupons;
    45	        this.formasPagamento = formasPagamento;
    46	    }
    48	    public Checkout calcular(DadosCompra dados) {
    49	        List<ItemPrecificado> itens = precificar(dados.itens());
    50	        NivelClube nivel = niveis.buscar(dados.nivelClube()).orElseThrow(() -> recusa("NIVEL_CLUBE_INVALIDO"));
    51	        Regiao regiao = Regiao.de(dados.regiao()).orElseThrow(() -> recusa("REGIAO_INVALIDA"));
    52	        if (dados.cep() == null || !CEP.matcher(dados.cep()).matches()) {
    53	            throw recusa("CEP_INVALIDO");
    54	        }
    55	        ModalidadeEntrega modalidade = modalidades.buscar(dados.modalidadeEntrega())
    56	                .orElseThrow(() -> recusa("MODALIDADE_INVALIDA"));
    59	        BigDecimal subtotal = Dinheiro.arredondar(itens.stream().map(ItemPrecificado::valor).reduce(BigDecimal.ZERO, BigDecimal::add));
    60	        BigDecimal pesoKg = itens.stream().map(ItemPrecificado::pesoKg).reduce(BigDecimal.ZERO, BigDecimal::add);
    63	        CotacaoEntrega entrega = modalidade.cotar(new PedidoParaEntrega(dados.cep(), regiao, pesoKg, subtotal));
    64	        BigDecimal frete = nivel.freteGratis(modalidade) ? Dinheiro.ZERO : Dinheiro.arredondar(entrega.frete());
    67	        boolean usouCupom = dados.cupom() != null;
    68	        BigDecimal desconto = usouCupom
    69	                ? cupons.desconto(dados.cupom(), new PedidoParaCupom(dados.cpf(), itens, subtotal, modalidade, frete))
    70	                : Dinheiro.ZERO;
    73	        BigDecimal seguro = regiao.seguro(subtotal);
    74	        BigDecimal totalPedido = Dinheiro.arredondar(subtotal.subtract(desconto).add(frete).add(seguro));
    77	        FormaPagamento forma = formasPagamento.buscar(dados.formaPagamento())
    78	                .orElseThrow(() -> recusa("FORMA_PAGAMENTO_INVALIDA"));
    79	        if (dados.parcelas() == null || !forma.aceitaParcelas(dados.parcelas())) {
    80	            throw recusa("PARCELAMENTO_INVALIDO");
    81	        }
    82	        if (!forma.disponivelPara(totalPedido)) {
    83	            throw recusa("FORMA_PAGAMENTO_INDISPONIVEL");
    84	        }
    85	        CondicaoPagamento pagamento = forma.condicao(totalPedido, dados.parcelas(), usouCupom);
    86	        BigDecimal totalFinal = Dinheiro.arredondar(pagamento.totalFinal());
    88	        Resumo resumo = new Resumo(
    89	                subtotal,
    90	                desconto,
    91	                frete,
    92	                entrega.prazoDias(),
    93	                seguro,
    94	                totalFinal.subtract(totalPedido),
    95	                totalFinal,
    96	                pagamento.parcelas(),
    97	                Dinheiro.arredondar(pagamento.valorParcela()),
    98	                Dinheiro.arredondar(nivel.credito(subtotal)),
    99	                nivel.brinde(subtotal));
   100	        return new Checkout(dados, itens, resumo);
   101	    }
   104	    private List<ItemPrecificado> precificar(List<ItemCompra> carrinho) {
   105	        Map<String, Produto> catalogo = produtos.buscarVarios(carrinho.stream().map(ItemCompra::sku).toList());
   106	        if (carrinho.stream().anyMatch(item -> !catalogo.containsKey(item.sku()))) {
   107	            throw recusa("PRODUTO_INEXISTENTE");
   108	        }
   109	        if (carrinho.stream().anyMatch(item -> catalogo.get(item.sku()).foraDeLinha())) {
   110	            throw recusa("PRODUTO_FORA_DE_LINHA");
   111	        }
   112	        if (carrinho.stream().anyMatch(item -> catalogo.get(item.sku()).estoque() < item.quantidade())) {
   113	            throw recusa("ESTOQUE_INSUFICIENTE");
   114	        }
   115	        return carrinho.stream()
   116	                .map(item -> {
   117	                    Produto produto = catalogo.get(item.sku());
   118	                    return new ItemPrecificado(item.sku(), item.quantidade(), produto.preco(), produto.pesoKg());
   119	                })
   120	                .toList();
   121	    }
   123	    private static ErroNegocio recusa(String codigo) {
   124	        return ErroNegocio.naoProcessavel(codigo);
   125	    }
   126	}
