    29	    public static DadosCompra ler(Object corpo) {
    30	        if (!(corpo instanceof Map<?, ?> dados)) {
    31	            throw invalido();
    32	        }
    33	        List<ItemCompra> itens = lerItens(dados.get("itens"));
    34	        String cpf = null;
    35	        String email = null;
    36	        if (dados.get("cliente") instanceof Map<?, ?> cliente) {
    37	            cpf = Json.texto(cliente.get("cpf"));
    38	            email = Json.texto(cliente.get("email"));
    39	        }
    40	        if (cpf == null || email == null) {
    41	            throw invalido();
    42	        }
    43	        Object cupom = dados.get("cupom");
    44	        Object parcelas = dados.get("parcelas");
    45	        return new DadosCompra(
    46	                cpf,
    47	                email,
    48	                itens,
    49	                Json.texto(dados.get("cep")),
    50	                Json.texto(dados.get("regiao")),
    51	                Json.texto(dados.get("modalidadeEntrega")),
    52	                cupom == null ? null : String.valueOf(cupom),
    53	                Json.texto(dados.get("formaPagamento")),
    54	                parcelas == null ? Integer.valueOf(1) : Json.inteiroPequeno(parcelas),
    55	                Json.texto(dados.get("nivelClube")));
    56	    }
    58	    private static List<ItemCompra> lerItens(Object valor) {
    59	        if (!(valor instanceof List<?> lista) || lista.isEmpty()) {
    60	            throw invalido();
    61	        }
    62	        List<ItemCompra> itens = new ArrayList<>();
    63	        Set<String> skus = new HashSet<>();
    64	        for (Object elemento : lista) {
    65	            if (!(elemento instanceof Map<?, ?> item)) {
    66	                throw invalido();
    67	            }
    68	            String sku = Json.texto(item.get("sku"));
    69	            Long lida = Json.inteiro(item.get("quantidade"));
    71	            Integer quantidade = lida == null || lida <= 0 ? null : (int) Math.min(lida, Integer.MAX_VALUE);
    72	            if (sku == null || quantidade == null || quantidade <= 0 || !skus.add(sku)) {
    73	                throw invalido();
    74	            }
    75	            itens.add(new ItemCompra(sku, quantidade));
    76	        }
    77	        return List.copyOf(itens);
    78	    }
    80	    private static ErroNegocio invalido() {
    81	        return ErroNegocio.naoProcessavel("PEDIDO_INVALIDO");
    82	    }
    83	}
