   104	    private List<ItemPrecificado> precificar(List<ItemCompra> carrinho) {
   105	        Map<String, Produto> catalogo = produtos.buscarVarios(carrinho.stream().map(ItemCompra::sku).toList());
   106	        if (carrinho.stream().anyMatch(item -> !catalogo.containsKey(item.sku()))) {
   107	            throw recusa("PRODUTO_INEXISTENTE");
   108	        }
   109	        if (carrinho.stream().anyMatch(item -> catalogo.get(item.sku()).foraDeLinha())) {
   110	            throw recusa("PRODUTO_FORA_DE_LINHA");
   111	        }
   112	        if (carrinho.stream().anyMatch(item -> catalogo.get(item.sku()).estoque() < item.quantidade())) {
   113	            throw recusa("ESTOQUE_INSUFICIENTE");
   114	        }
   115	        return carrinho.stream()
   116	                .map(item -> {
   117	                    Produto produto = catalogo.get(item.sku());
   118	                    return new ItemPrecificado(item.sku(), item.quantidade(), produto.preco(), produto.pesoKg());
   119	                })
   120	                .toList();
