    21	import tools.jackson.databind.ObjectMapper;
    24	@Component
    25	public class TransLog implements Transportadora {
    27	    private static final Logger log = LoggerFactory.getLogger(TransLog.class);
    29	    private final String url;
    30	    private final Duration tempoLimite;
    31	    private final ObjectMapper json;
    32	    private final HttpClient http;
    34	    public TransLog(@Value("${translog.url:}") String url,
    35	                    @Value("${translog.tempo-limite:2s}") Duration tempoLimite,
    36	                    ObjectMapper json) {
    37	        this.url = url.strip().replaceAll("/+$", "");
    38	        this.tempoLimite = tempoLimite;
    39	        this.json = json;
    40	        this.http = HttpClient.newBuilder()
    41	                .version(HttpClient.Version.HTTP_1_1)
    42	                .connectTimeout(tempoLimite)
    43	                .build();
    44	    }
    46	    @Override
    47	    public CotacaoTransportadora cotar(String cep, long pesoGramas, ServicoTransporte servico) {
    48	        if (url.isEmpty()) {
    49	            throw new TransportadoraForaDoArException("TRANSLOG_URL não configurada");
    50	        }
    51	        Map<?, ?> resposta = consultar(cep, pesoGramas, servico);
    52	        Object erro = resposta.get("error");
    53	        if (erro != null) {
    54	            if ("ZIP_NOT_SERVED".equals(erro)) {
    55	                throw new CepNaoAtendidoException(cep);
    56	            }
    57	            throw new TransportadoraForaDoArException("Erro da TransLog: " + erro);
    58	        }
    59	        Long precoCentavos = Json.inteiro(resposta.get("price_cents"));
    60	        Long prazoHoras = Json.inteiro(resposta.get("eta_hours"));
    61	        if (precoCentavos == null || precoCentavos < 0 || prazoHoras == null || prazoHoras < 0) {
    62	            throw new TransportadoraForaDoArException("Resposta inesperada da TransLog: " + resposta);
    63	        }
    64	        return new CotacaoTransportadora(BigDecimal.valueOf(precoCentavos, 2), Math.toIntExact(Math.ceilDiv(prazoHoras, 24)));
    65	    }
    67	    private Map<?, ?> consultar(String cep, long pesoGramas, ServicoTransporte servico) {
    68	        URI uri = URI.create(url + "/v2/quote?zip=" + URLEncoder.encode(cep, StandardCharsets.UTF_8)
    69	                + "&weight_g=" + pesoGramas
    70	                + "&service=" + codigo(servico));
    71	        HttpRequest requisicao = HttpRequest.newBuilder(uri).timeout(tempoLimite).GET().build();
    72	        CompletableFuture<HttpResponse<String>> futuro = http.sendAsync(requisicao, HttpResponse.BodyHandlers.ofString());
    73	        HttpResponse<String> resposta;
    74	        try {
    75	            resposta = futuro.get(tempoLimite.toMillis(), TimeUnit.MILLISECONDS);
    76	        } catch (TimeoutException e) {
    77	            futuro.cancel(true);
    78	            throw new TransportadoraForaDoArException("TransLog não respondeu a tempo", e);
    79	        } catch (InterruptedException e) {
    80	            Thread.currentThread().interrupt();
    81	            throw new TransportadoraForaDoArException("Consulta à TransLog interrompida", e);
    82	        } catch (ExecutionException e) {
    83	            log.warn("Falha ao consultar a TransLog: {}", e.getCause().toString());
    84	            throw new TransportadoraForaDoArException("Falha ao consultar a TransLog", e.getCause());
    85	        }
    86	        if (resposta.statusCode() != 200) {
    87	            throw new TransportadoraForaDoArException("TransLog respondeu " + resposta.statusCode());
    88	        }
    89	        try {
    90	            if (json.readValue(resposta.body(), Object.class) instanceof Map<?, ?> corpo) {
    91	                return corpo;
    92	            }
    93	        } catch (RuntimeException e) {
    94	            throw new TransportadoraForaDoArException("Resposta ilegível da TransLog", e);
    95	        }
    96	        throw new TransportadoraForaDoArException("Resposta inesperada da TransLog");
    97	    }
    99	    private static String codigo(ServicoTransporte servico) {
   100	        return switch (servico) {
   101	            case ECONOMICO -> "STD";
   102	            case EXPRESSO -> "EXP";
   103	        };
   104	    }
   105	}
