     9	@Component
    10	public class Cartao implements FormaPagamento {
    12	    private static final int MAXIMO_PARCELAS = 12;
    13	    private static final int MAXIMO_SEM_JUROS = 3;
    14	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
    15	    private static final MathContext PRECISAO = MathContext.DECIMAL128;
    17	    @Override
    18	    public String codigo() {
    19	        return "CARTAO";
    20	    }
    22	    @Override
    23	    public boolean aceitaParcelas(int parcelas) {
    24	        return parcelas >= 1 && parcelas <= MAXIMO_PARCELAS;
    25	    }
    27	    @Override
    28	    public CondicaoPagamento condicao(BigDecimal totalPedido, int parcelas, boolean usouCupom) {
    29	        if (parcelas <= MAXIMO_SEM_JUROS) {
    30	            BigDecimal parcela = Dinheiro.arredondar(totalPedido.divide(BigDecimal.valueOf(parcelas), PRECISAO));
    31	            return new CondicaoPagamento(totalPedido, parcelas, parcela);
    32	        }
    34	        BigDecimal fator = BigDecimal.ONE.add(TAXA_MENSAL).pow(-parcelas, PRECISAO);
    35	        BigDecimal parcela = Dinheiro.arredondar(
    36	                totalPedido.multiply(TAXA_MENSAL).divide(BigDecimal.ONE.subtract(fator), PRECISAO));
    37	        return new CondicaoPagamento(Dinheiro.arredondar(parcela.multiply(BigDecimal.valueOf(parcelas))), parcelas, parcela);
    38	    }
    39	}
