    65	    public Pedido registrarPagamento(long id, String idTransacao, Instant pagoEm) {
    66	        Desfecho desfecho = transacao.execute(status -> {
    67	            Pedido pedido = pedidos.travar(id).orElseThrow(PedidoService::naoEncontrado);
    68	            if (idTransacao == null || pagoEm == null) {
    69	                throw requisicaoInvalida();
    70	            }
    71	            if (idTransacao.equals(pedido.idTransacao())) {
    72	                return new Desfecho(pedido, null);
    73	            }
    74	            exigirMudanca(pedido, SituacaoPedido.PAGO);
    75	            if (Duration.between(pedido.criadoEm(), pagoEm).compareTo(PRAZO_PAGAMENTO) > 0) {
    76	                return new Desfecho(cancelarTravado(pedido), ErroNegocio.conflito("PEDIDO_EXPIRADO"));
    77	            }
    78	            if (!estoque.baixar(pedido.quantidades())) {
    79	                return new Desfecho(cancelarTravado(pedido), ErroNegocio.conflito("ESTOQUE_INSUFICIENTE"));
    80	            }
    81	            pedidos.registrarPagamento(id, idTransacao, pagoEm);
