    29	    @Transactional(propagation = Propagation.MANDATORY)
    30	    public boolean baixar(Map<String, Integer> quantidades) {
    31	        Map<String, Integer> emOrdem = new TreeMap<>(quantidades);
    33	        Map<String, Integer> disponivel = new TreeMap<>();
    34	        for (String sku : emOrdem.keySet()) {
    35	            jdbc.sql("SELECT estoque FROM produto WHERE sku = :sku FOR UPDATE")
    36	                    .param("sku", sku)
    37	                    .query(Integer.class)
    38	                    .optional()
    39	                    .ifPresent(estoque -> disponivel.put(sku, estoque));
    40	        }
    41	        boolean suficiente = emOrdem.entrySet().stream()
    42	                .allMatch(item -> disponivel.getOrDefault(item.getKey(), 0) >= item.getValue());
    43	        if (!suficiente) {
    44	            return false;
    45	        }
    46	        emOrdem.forEach((sku, quantidade) -> {
    47	            int alterados = jdbc.sql("UPDATE produto SET estoque = estoque - :quantidade WHERE sku = :sku AND estoque >= :quantidade")
    48	                    .param("quantidade", quantidade)
    49	                    .param("sku", sku)
    50	                    .update();
    51	            if (alterados != 1) {
    52	                throw new IllegalStateException("Estoque mudou durante a baixa do produto " + sku);
    53	            }
    54	        });
    55	        return true;
    56	    }
